import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph Month 2021: RGW Update","description":"","frontmatter":{"title":"Ceph Month 2021: RGW Update","date":"2021-06-10T00:00:00.000Z","updated":"2021-06-11T00:00:00.000Z","tags":["Ceph","RGW","S3 Select","S3 Bucket Inventory","Multi","site Support"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Month_2021_-_RGW_Update.md","filePath":"posts/2021/Ceph_Month_2021_-_RGW_Update.md","lastUpdated":1780459816000}'),i={name:"posts/2021/Ceph_Month_2021_-_RGW_Update.md"};function l(n,t,s,p,h,c){return a(),o("div",null,[...t[0]||(t[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph-月度会议-第二周" tabindex="-1">会议主题：Ceph 月度会议 - 第二周 <a class="header-anchor" href="#会议主题-ceph-月度会议-第二周" aria-label="Permalink to &quot;会议主题：Ceph 月度会议 - 第二周&quot;">​</a></h4><h4 id="会议时间-2021年6月10日" tabindex="-1">会议时间：2021年6月10日 <a class="header-anchor" href="#会议时间-2021年6月10日" aria-label="Permalink to &quot;会议时间：2021年6月10日&quot;">​</a></h4><h4 id="参会人员-ceph-社区成员、研发人员、相关领域专家" tabindex="-1">参会人员：Ceph 社区成员、研发人员、相关领域专家 <a class="header-anchor" href="#参会人员-ceph-社区成员、研发人员、相关领域专家" aria-label="Permalink to &quot;参会人员：Ceph 社区成员、研发人员、相关领域专家&quot;">​</a></h4><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><ol><li><p><strong>RGW 更新介绍</strong>：</p><ul><li><strong>S3 Select 功能</strong>：Pacific 版本新增，支持对 CSV 格式的对象进行类似 SQL 的查询。Quincy 版本将扩展查询类型和函数支持，并增加对 Parquet 格式的支持，提高查询执行效率。</li><li><strong>S3 Bucket Inventory</strong>：后台进程构建大型桶的索引，提高列表和搜索性能。</li><li><strong>SSE S3 Bucket 加密</strong>：透明、基于策略的对象加密，无需客户端在上传时请求加密。</li><li><strong>请求速率限制</strong>：已实现概念验证，预计在 Quincy 版本中推出。</li><li><strong>数据缓存项目</strong>：与 Mass Open Cloud 合作，旨在通过本地数据缓存加速工作负载。</li><li><strong>Jaeger 追踪支持</strong>：计划在 RGW 中构建 Jaeger 追踪支持，用于性能评估和优化。</li><li><strong>Project Zipper</strong>：由 Dan Grinowicz 领导的项目，构建了一个抽象层，允许接入非 RADOS 后端或在其上堆叠层。</li><li><strong>多站点支持</strong>：包括动态重共享支持、生命周期过渡到云服务、从云同步等。</li></ul></li><li><p><strong>讨论与提问</strong>：</p><ul><li><strong>S3 Select 和 Bucket Inventory</strong>：讨论了速率限制的实现细节。</li><li><strong>Project Zipper</strong>：讨论了对不同后端的支持以及在多站点环境中的应用。</li><li><strong>数据缓存</strong>：询问了数据缓存是否使用 Nginx 缓存，以及是否可以直接在 RGW 中实现。</li><li><strong>版本支持</strong>：询问了新功能是否会回溯支持到 Pacific 版本。</li><li><strong>Ganesha 导出支持</strong>：讨论了在多站点环境中的应用。</li><li><strong>索引格式</strong>：询问了索引格式是否会在未来版本中发生变化。</li></ul></li><li><p><strong>后续行动计划</strong>：</p><ul><li>继续推进 S3 Select、Bucket Inventory、速率限制等功能的开发和测试。</li><li>完善 Project Zipper 的多后端支持，并探索在边缘部署中的应用。</li><li>加强数据缓存项目的研究和开发，考虑在 RGW 中直接实现缓存功能。</li><li>继续测试和优化多站点支持，特别是动态重共享和生命周期过渡到云服务。</li></ul></li></ol><h4 id="会议结束语" tabindex="-1">会议结束语： <a class="header-anchor" href="#会议结束语" aria-label="Permalink to &quot;会议结束语：&quot;">​</a></h4><p>感谢 Casey 的详细更新和所有参会者的积极参与。期待在后续的开发和测试中取得更多进展。</p>',8)])])}const g=e(i,[["render",l]]);export{_ as __pageData,g as default};
